import catalog from "../../src-tauri/resources/asr_catalog.json";

/** One downloadable local model. Generated by `scripts/sync_asr_catalog.py`. */
export interface CatalogModel {
  key: string;
  name: string;
  description: string;
  repo_id: string;
  filename: string;
  revision: string;
  size: number;
  sha256: string;
  license: string;
  recommended: boolean;
  /** The model can translate speech natively. */
  translation: boolean;
  languages: string[];
  /** Conditions recognition on Smart Vocabulary; otherwise correction only. */
  vocabulary: boolean;
  kv_type?: string;
}

export interface AsrCatalog {
  source: string;
  engine_version: string;
  source_commit: string;
  models: CatalogModel[];
}

// The generated file is validated by src-tauri/resources/test_local_engine_contract.py.
// JSON widens tuples to arrays, so the cast goes through `unknown`.
export const ASR_CATALOG = catalog as unknown as AsrCatalog;
export const CATALOG_MODELS: readonly CatalogModel[] = ASR_CATALOG.models;

const byKey = new Map(CATALOG_MODELS.map((model) => [model.key, model]));

export function findCatalogModel(key: string): CatalogModel | undefined {
  return byKey.get(key);
}

/** Decimal MB/GB, matching the sizes SpeakFlow already showed for these models. */
export function formatModelSize(bytes: number): string {
  if (bytes >= 1_000_000_000) return `${(bytes / 1_000_000_000).toFixed(2)} GB`;
  return `${Math.round(bytes / 1_000_000)} MB`;
}

export interface CatalogLanguage {
  code: string;
  modelCount: number;
}

/** Languages offered by the catalog, most-covered first, then alphabetical. */
export function catalogLanguages(models: readonly CatalogModel[] = CATALOG_MODELS): CatalogLanguage[] {
  const counts = new Map<string, number>();
  for (const model of models) {
    for (const code of model.languages) counts.set(code, (counts.get(code) ?? 0) + 1);
  }
  return [...counts.entries()]
    .map(([code, modelCount]) => ({ code, modelCount }))
    .sort((a, b) => b.modelCount - a.modelCount || a.code.localeCompare(b.code));
}

/** English name for a language code; the app interface is English-only. */
export function languageName(code: string): string {
  try {
    return new Intl.DisplayNames(["en"], { type: "language" }).of(code) ?? code;
  } catch {
    return code;
  }
}
